// ESCUTA: ativação por voz. Diga "JARVIS" e ele começa a ouvir, sem botão.
// Funciona só com a página aberta, na frente e com a tela ligada.
// Precisa do script.js, voz.js e cerebro.js carregados antes.
const Escuta = (function () {
  const Reconhecimento = window.SpeechRecognition || window.webkitSpeechRecognition;
    const PREFERENCIA = "jarvis_escuta";
      const SILENCIO_MS = 2500;   // quanto silêncio espera antes de achar que você terminou
        const ESPERA_INICIAL_MS = 9000;

          // Como o reconhecimento costuma escrever "JARVIS": jarvis, jarves, charves, charvis, garvis, jarbas...
            const PALAVRA = /^(ch|dj|j|g|x|c)ar(v|b)(i|e|a)(s|z)$/;
              // Quando ele separa em duas palavras
                const DUAS_PALAVRAS = ["ja vis", "ja ves", "jar vis", "jar ves", "char vis", "char ves"];

                  let ligado = false;
                    let rec = null;            // o reconhecimento que está rodando agora
                      let esperaComando = false; // depois do "JARVIS", juntando o que você fala
                        let acumulado = "";
                          let temporizador = null;
                            let pausaAte = 0;
                              let ponto = null;

                                function limpar(texto) {
                                    return texto.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                                      }

                                        // Procura a palavra de ativação. Devolve o que vem DEPOIS dela (com a escrita original),
                                          // ou null se ela não foi dita.
                                            function achar(texto) {
                                                const t = limpar(texto);
                                                    const palavras = /[a-z]+/g;
                                                        let m;
                                                            while ((m = palavras.exec(t)) !== null) {
                                                                  if (PALAVRA.test(m[0])) return cortar(texto, m.index + m[0].length);
                                                                      }
                                                                          for (let i = 0; i < DUAS_PALAVRAS.length; i++) {
                                                                                const pos = t.indexOf(DUAS_PALAVRAS[i]);
                                                                                      if (pos !== -1) return cortar(texto, pos + DUAS_PALAVRAS[i].length);
                                                                                          }
                                                                                              return null;
                                                                                                }

                                                                                                  function cortar(texto, de) {
                                                                                                      return texto.slice(de).replace(/^[\s,.!?:;-]+/, "").trim();
                                                                                                        }

                                                                                                          function parar() {
                                                                                                              if (rec) {
                                                                                                                    const antigo = rec;
                                                                                                                          rec = null;
                                                                                                                                try { antigo.abort(); } catch (e) { /* sem problema */ }
                                                                                                                                    }
                                                                                                                                      }

                                                                                                                                        function agendarFim(ms) {
                                                                                                                                            clearTimeout(temporizador);
                                                                                                                                                temporizador = setTimeout(concluir, ms);
                                                                                                                                                  }

                                                                                                                                                    // Você parou de falar: manda o pedido para o JARVIS
                                                                                                                                                      function concluir() {
                                                                                                                                                          temporizador = null;
                                                                                                                                                              if (!esperaComando) return;
                                                                                                                                                                  esperaComando = false;
                                                                                                                                                                      const pedido = acumulado.trim();
                                                                                                                                                                          acumulado = "";
                                                                                                                                                                              if (!pedido) { mudarEstado("idle"); return; }

                                                                                                                                                                                  // Comando para a própria escuta
                                                                                                                                                                                      if (/(desativ|deslig|par[ae]).*(escut|ativacao)/.test(limpar(pedido))) {
                                                                                                                                                                                            desligar();
                                                                                                                                                                                                  avisar("Ativação por voz desligada. Toque na tela para ligar de novo.");
                                                                                                                                                                                                        return;
                                                                                                                                                                                                            }
                                                                                                                                                                                                                executar(pedido);
                                                                                                                                                                                                                  }

                                                                                                                                                                                                                    // Manda o pedido para o JARVIS pensar e responder (o mesmo caminho do botão do microfone)
                                                                                                                                                                                                                      function executar(pedido) {
                                                                                                                                                                                                                          parar();
                                                                                                                                                                                                                              ocupado = true;
                                                                                                                                                                                                                                  legenda.textContent = pedido;
                                                                                                                                                                                                                                      processar(pedido);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                          // Fala uma frase e volta ao normal
                                                                                                                                                                                                                                            function avisar(frase) {
                                                                                                                                                                                                                                                parar();
                                                                                                                                                                                                                                                    ocupado = true;
                                                                                                                                                                                                                                                        legenda.textContent = frase;
                                                                                                                                                                                                                                                            mudarEstado("respondendo");
                                                                                                                                                                                                                                                                Voz.falar(frase, liberar);
                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                    // Só disse "JARVIS": responde e espera o pedido
                                                                                                                                                                                                                                                                      function acordar() {
                                                                                                                                                                                                                                                                          parar();
                                                                                                                                                                                                                                                                              ocupado = true;
                                                                                                                                                                                                                                                                                  legenda.textContent = "Estou ouvindo.";
                                                                                                                                                                                                                                                                                      mudarEstado("respondendo");
                                                                                                                                                                                                                                                                                          Voz.falar("Estou ouvindo.", function () {
                                                                                                                                                                                                                                                                                                ocupado = false;
                                                                                                                                                                                                                                                                                                      esperaComando = true;
                                                                                                                                                                                                                                                                                                            acumulado = "";
                                                                                                                                                                                                                                                                                                                  mudarEstado("ouvindo");
                                                                                                                                                                                                                                                                                                                        agendarFim(ESPERA_INICIAL_MS);
                                                                                                                                                                                                                                                                                                                              iniciar();
                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                      // Decide o que fazer com o que foi ouvido
                                                                                                                                                                                                                                                                                                                                        function tratar(texto, final) {
                                                                                                                                                                                                                                                                                                                                            if (esperaComando) {
                                                                                                                                                                                                                                                                                                                                                  if (final) {
                                                                                                                                                                                                                                                                                                                                                          const depois = achar(texto);
                                                                                                                                                                                                                                                                                                                                                                  acumulado += " " + (depois !== null ? depois : texto);
                                                                                                                                                                                                                                                                                                                                                                          legenda.textContent = acumulado.trim();
                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                        legenda.textContent = (acumulado + " " + texto).trim();
                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                    agendarFim(SILENCIO_MS); // cada palavra nova reinicia a espera
                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                  if (!final) return;
                                                                                                                                                                                                                                                                                                                                                                                                                      const depois = achar(texto);
                                                                                                                                                                                                                                                                                                                                                                                                                          if (depois === null) return;            // não falou "JARVIS": ignora
                                                                                                                                                                                                                                                                                                                                                                                                                              if (depois.length >= 3) {               // "JARVIS, me explica isso..." (pode continuar falando)
                                                                                                                                                                                                                                                                                                                                                                                                                                    esperaComando = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                          acumulado = depois;
                                                                                                                                                                                                                                                                                                                                                                                                                                                mudarEstado("ouvindo");
                                                                                                                                                                                                                                                                                                                                                                                                                                                      legenda.textContent = depois;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            agendarFim(SILENCIO_MS);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      acordar();                            // só "JARVIS"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function iniciar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!ligado || rec || !Reconhecimento) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const r = new Reconhecimento();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          r.lang = "pt-BR";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              r.continuous = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  r.interimResults = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      r.onresult = function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (rec !== r) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (let i = e.resultIndex; i < e.results.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tratar(e.results[i][0].transcript, e.results[i].isFinal);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (rec !== r) return; // o JARVIS assumiu a conversa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                r.onerror = function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (rec !== r) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (e.error === "not-allowed" || e.error === "service-not-allowed") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    desligar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            legenda.textContent = "Preciso da permissão do microfone. Libere nas configurações do site.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (e.error !== "no-speech" && e.error !== "aborted") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          pausaAte = Date.now() + 4000; // algo deu errado: espera antes de tentar de novo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        r.onend = function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (rec === r) rec = null; // o ciclo abaixo religa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rec = r;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try { r.start(); } catch (e) { rec = null; pausaAte = Date.now() + 3000; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // A cada instante, garante que está escutando quando deve e quieto quando não deve
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function ciclo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!ligado) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (ocupado) {               // o JARVIS está falando ou ouvindo pelo botão
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              esperaComando = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    clearTimeout(temporizador);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          parar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!rec && Date.now() > pausaAte) iniciar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function salvar(valor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try { localStorage.setItem(PREFERENCIA, valor); } catch (e) { /* sem problema */ }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarPonto() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ponto.style.background = ligado ? "#5cff9c" : "#4a5a78";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ponto.title = ligado ? "Ativação por voz ligada: diga JARVIS" : "Ativação por voz desligada: toque na tela";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function ligar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!Reconhecimento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          legenda.textContent = "Este navegador não tem reconhecimento de voz. Use o Chrome.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ligado = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvar("1");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarPonto();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ciclo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function desligar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ligado = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    esperaComando = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        clearTimeout(temporizador);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            parar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar("0");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarPonto();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Um toque em qualquer lugar: liga (e é o toque que o navegador exige para liberar o microfone)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function aoTocar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!ligado) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (ligar() && !ocupado) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            avisar("Ativação por voz ligada. Diga Jarvis quando precisar. Para desligar, diga: Jarvis, desligar escuta.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else if (!rec && !ocupado) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            iniciar(); // se a escuta tinha falhado, tenta de novo agora que há um toque
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function criarPonto() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ponto = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ponto.style.cssText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "position:fixed;top:12px;right:12px;width:10px;height:10px;border-radius:50%;" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "background:#4a5a78;z-index:10;pointer-events:none;opacity:.9";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.body.appendChild(ponto);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarPonto();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    criarPonto();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.addEventListener("click", aoTocar);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setInterval(ciclo, 700);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Se você já tinha ligado antes e o navegador já tem permissão, volta a ligar sozinho
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (localStorage.getItem(PREFERENCIA) === "1" && navigator.permissions) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      navigator.permissions.query({ name: "microphone" }).then(function (p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (p.state === "granted") ligar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }).catch(function () { /* sem problema */ });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (e) { /* sem problema */ }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return { tratar: tratar, achar: achar };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })();